#include <string.h>
#include <stdint.h>
#include <arpa/inet.h>
#include <netinet/in.h>

struct proxy_header_v2 {
    uint8_t sig[12];
    uint8_t cmd_ver;
    uint8_t fam;
    uint16_t len;
    union {
        struct {
            in_addr_t src_addr;
            in_addr_t dst_addr;
            uint16_t src_port;
            uint16_t dst_port;
        } ip4;
        struct {
            struct in6_addr src_addr;
            struct in6_addr dst_addr;
            uint16_t src_port;
            uint16_t dst_port;
        } ip6;
    } addr;
};

int main() {
    static char data_copy[32767] = {0};
    unsigned char input[16] = {0x0d,0x0a,0x0d,0x0a,0x00,0x0d,0x0a,0x51,0x55,0x49,0x54,0x0a,0x21,0x11,0x00,0x28};
    memcpy(data_copy, input, 16);
    size_t length = 16;

    struct proxy_header_v2 *hdr = (struct proxy_header_v2 *)data_copy;
    const unsigned int proto_signature_length = 16;
    unsigned int size;
    enum { LOCAL = 0x20, PROXY = 0x21, TCP4 = 0x11, TCP6 = 0x21 };

    printf("sizeof(*hdr)=%zu\n", sizeof(*hdr));
    printf("hdr->len raw = %u\n", hdr->len);
    printf("ntohs(hdr->len) = %u\n", ntohs(hdr->len));

    size = proto_signature_length + (unsigned int)ntohs(hdr->len);
    printf("size = %u\n", size);
    if (size > (unsigned int)sizeof(*hdr)) {
        printf("return NULL (size too big)\n");
        return 0;
    }

    char *buffer = data_copy;
    if (hdr->cmd_ver == PROXY) {
        if (hdr->fam == TCP4) {
            printf("TCP4 branch\n");
        } else if (hdr->fam == TCP6) {
            printf("TCP6 branch\n");
        } else {
            printf("return NULL (bad fam)\n");
            return 0;
        }
    } else if (hdr->cmd_ver == LOCAL) {
        printf("LOCAL branch\n");
    } else {
        printf("return NULL (bad cmd_ver)\n");
        return 0;
    }

    buffer += size;
    size_t adjusted_size = (size_t)(data_copy + length - buffer);
    printf("adjusted_size = %zu (0x%zx)\n", adjusted_size, adjusted_size);
    char *crlfcrlf = memmem(buffer, adjusted_size, "\r\n\r\n", 4);
    printf("crlfcrlf = %p\n", (void*)crlfcrlf);
    return 0;
}
EOF
